/* Coupled-domain tuples (coupled_subgroups2_): the group of joint domain
 * permutations generated by the slots' per-operation actions, and the
 * lexicographically first member of each orbit of domain tuples under it. */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum {
    DG_OK = 0,
    DG_MEMORY = 1,
    DG_RANGE = 2,
    DG_CAPACITY = 3,
};

typedef struct {
    int width;
    size_t cap, count;
    int32_t *items;
    int *used;
} set32;

static uint64_t hash_items(const int32_t *v, int width)
{
    uint64_t h = 1469598103934665603ull;
    for (int i = 0; i < width; i++) {
        h ^= (uint32_t)v[i];
        h *= 1099511628211ull;
    }
    h ^= h >> 31;
    h *= 0xbf58476d1ce4e5b9ull;
    return h ^ (h >> 29);
}

static int set_init(set32 *s, int width, size_t cap)
{
    s->width = width;
    s->cap = cap;
    s->count = 0;
    s->items = malloc(sizeof(int32_t) * (size_t)width * cap);
    s->used = calloc(cap, sizeof(int));
    return s->items && s->used ? 0 : DG_MEMORY;
}

static void set_free(set32 *s)
{
    free(s->items);
    free(s->used);
}

/* 1 when newly added, 0 when present, negative on error. */
static int set_add(set32 *s, const int32_t *v)
{
    if (2 * (s->count + 1) > s->cap) {
        set32 grown;
        if (set_init(&grown, s->width, s->cap * 2)) return -DG_MEMORY;
        for (size_t i = 0; i < s->cap; i++)
            if (s->used[i]) set_add(&grown, s->items + i * s->width);
        set_free(s);
        *s = grown;
    }
    size_t mask = s->cap - 1, i = hash_items(v, s->width) & mask;
    while (s->used[i]) {
        if (!memcmp(s->items + i * s->width, v, sizeof(int32_t) * (size_t)s->width)) return 0;
        i = (i + 1) & mask;
    }
    s->used[i] = 1;
    memcpy(s->items + i * s->width, v, sizeof(int32_t) * (size_t)s->width);
    s->count++;
    return 1;
}

static int set_has(const set32 *s, const int32_t *v)
{
    size_t mask = s->cap - 1, i = hash_items(v, s->width) & mask;
    while (s->used[i]) {
        if (!memcmp(s->items + i * s->width, v, sizeof(int32_t) * (size_t)s->width)) return 1;
        i = (i + 1) & mask;
    }
    return 0;
}

/* actions: op_count joint actions, each the concatenation of the slots'
 * permutations (slot s has sizes[s] domains); out: retained domain tuples,
 * slot_count per tuple.  Returns the tuple count or a negative error. */
int relative_domain_tuples(int slot_count, const int *sizes, int op_count, const int32_t *actions, int64_t capacity,
                           int32_t *out)
{
    int width = 0;
    int offsets[64];
    if (slot_count <= 0 || slot_count > 64) return -DG_RANGE;
    for (int s = 0; s < slot_count; s++) {
        if (sizes[s] <= 0) return -DG_RANGE;
        offsets[s] = width;
        width += sizes[s];
    }
    set32 distinct;
    if (set_init(&distinct, width, 1024)) return -DG_MEMORY;
    int status = DG_OK;
    int32_t *generators = malloc(sizeof(int32_t) * (size_t)width * (size_t)(op_count + 1));
    int generator_count = 0;
    if (!generators) status = DG_MEMORY;
    for (int op = 0; op < op_count && !status; op++) {
        const int32_t *a = actions + (size_t)op * width;
        for (int s = 0; s < slot_count; s++)
            for (int d = 0; d < sizes[s]; d++)
                if (a[offsets[s] + d] < 0 || a[offsets[s] + d] >= sizes[s]) status = DG_RANGE;
        if (status) break;
        int added = set_add(&distinct, a);
        if (added < 0) {
            status = -added;
            break;
        }
        if (added) memcpy(generators + (size_t)generator_count++ * width, a, sizeof(int32_t) * (size_t)width);
    }
    set_free(&distinct);
    /* Each orbit of the generated group is the closure of its first tuple
     * under the generators alone (the group is finite). */
    int64_t retained = 0;
    set32 seen;
    int32_t *queue = 0;
    size_t queue_cap = 0;
    /* A tuple's mixed-radix index marks it in a bitmap when the product of
     * the slot sizes is small enough; otherwise the hash set does. */
    uint64_t total = 1, radix[64];
    for (int s = slot_count - 1; s >= 0; s--) {
        radix[s] = total;
        total = total > ((uint64_t)1 << 40) ? total : total * (uint64_t)sizes[s];
    }
    uint64_t *bitmap = 0;
    if (!status && total <= ((uint64_t)1 << 30)) {
        bitmap = calloc((size_t)((total + 63) / 64), sizeof(uint64_t));
        if (!bitmap) status = DG_MEMORY;
    }
#define TUPLE_INDEX(v) ({ uint64_t _i = 0; for (int _s = 0; _s < slot_count; _s++) _i += (uint64_t)(v)[_s] * radix[_s]; _i; })
#define SEEN_HAS(v) (bitmap ? (int)((bitmap[TUPLE_INDEX(v) >> 6] >> (TUPLE_INDEX(v) & 63)) & 1) : set_has(&seen, (v)))
    if (!status && !bitmap && set_init(&seen, slot_count, 1024)) status = DG_MEMORY;
    if (!status) {
        int32_t candidate[64], image[64];
        for (int s = 0; s < slot_count; s++) candidate[s] = 0;
        while (!status) {
            if (!SEEN_HAS(candidate)) {
                if (retained >= capacity) {
                    status = DG_CAPACITY;
                    break;
                }
                memcpy(out + retained++ * slot_count, candidate, sizeof(int32_t) * (size_t)slot_count);
                if (bitmap) {
                    uint64_t index = TUPLE_INDEX(candidate);
                    bitmap[index >> 6] |= (uint64_t)1 << (index & 63);
                } else if (set_add(&seen, candidate) < 0) {
                    status = DG_MEMORY;
                    break;
                }
                size_t head = 0, tail = 0;
                if (queue_cap < 64) {
                    queue_cap = 64;
                    int32_t *grown = realloc(queue, sizeof(int32_t) * (size_t)slot_count * queue_cap);
                    if (!grown) {
                        status = DG_MEMORY;
                        break;
                    }
                    queue = grown;
                }
                memcpy(queue, candidate, sizeof(int32_t) * (size_t)slot_count);
                tail = 1;
                while (head < tail && !status) {
                    const int32_t *point = queue + head++ * slot_count;
                    for (int g = 0; g < generator_count && !status; g++) {
                        const int32_t *element = generators + (size_t)g * width;
                        for (int s = 0; s < slot_count; s++) image[s] = element[offsets[s] + point[s]];
                        int added;
                        if (bitmap) {
                            uint64_t index = TUPLE_INDEX(image), bit = (uint64_t)1 << (index & 63);
                            added = !(bitmap[index >> 6] & bit);
                            bitmap[index >> 6] |= bit;
                        } else {
                            added = set_add(&seen, image);
                        }
                        if (added < 0) {
                            status = DG_MEMORY;
                            break;
                        }
                        if (!added) continue;
                        if (tail == queue_cap) {
                            size_t at = (size_t)(point - queue);
                            queue_cap *= 2;
                            int32_t *grown = realloc(queue, sizeof(int32_t) * (size_t)slot_count * queue_cap);
                            if (!grown) {
                                status = DG_MEMORY;
                                break;
                            }
                            queue = grown;
                            point = queue + at;
                        }
                        memcpy(queue + tail++ * slot_count, image, sizeof(int32_t) * (size_t)slot_count);
                    }
                }
            }
            int s = slot_count - 1;
            while (s >= 0 && ++candidate[s] == sizes[s]) candidate[s--] = 0;
            if (s < 0) break;
        }
        if (!bitmap) set_free(&seen);
    }
#undef SEEN_HAS
#undef TUPLE_INDEX
    free(bitmap);
    free(queue);
    free(generators);
    return status ? -status : (int)retained;
}
